insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_ss_v1'
from (values
('113.14.c.1.A',3,'How can a new bridge change a community?','["it can make travel faster and bring new businesses", "it makes the town disappear", "it removes the river", "it stops all travel"]'::jsonb,0,'New roads and bridges change how people live.','original'),
('113.14.c.1.B',3,'Who designed the layout of streets for Washington, D.C.?','["Clara Barton", "Pierre-Charles L''Enfant", "Henry Ford", "Daniel Boone"]'::jsonb,1,'L''Enfant planned the capital city.','original'),
('113.14.c.1.B',3,'Benjamin Banneker helped shape communities by...','["painting murals", "inventing the airplane", "helping survey the land for the nation''s capital", "building the first car"]'::jsonb,2,'Banneker was a surveyor and scientist.','original'),
('113.14.c.1.B',3,'Benjamin Franklin helped his community by...','["building a spaceship", "fighting in the Civil War", "creating video games", "starting a library and a fire company"]'::jsonb,3,'Franklin founded community institutions.','original'),
('113.14.c.1.C',3,'Daniel Boone helped expand American settlement by...','["leading settlers through the Cumberland Gap", "inventing the telephone", "building the Panama Canal", "designing airplanes"]'::jsonb,0,'Boone blazed the Wilderness Road.','original'),
('113.14.c.1.C',4,'The Founding Fathers contributed to a new community by...','["building the Great Wall", "helping create a new nation", "flying to the moon", "discovering gold in Alaska"]'::jsonb,1,'They created the United States government.','original'),
('113.14.c.2.A',3,'Why did many people form communities?','["to avoid each other", "to hide from friends", "for safety and shared laws", "to stop trade"]'::jsonb,2,'Communities offer security.','original'),
('113.14.c.2.A',3,'Some people came to America seeking...','["faster phones", "new video games", "a longer school year", "religious freedom"]'::jsonb,3,'Many sought freedom of worship.','original'),
('113.14.c.2.B',3,'How do communities meet their need for communication?','["phones, mail, and the internet", "only carrier pigeons today", "only drums", "they do not communicate"]'::jsonb,0,'Communication tools connect people.','original'),
('113.14.c.2.B',3,'Which is a way communities meet the need for transportation?','["bookshelves", "buses and roads", "ovens", "chalk"]'::jsonb,1,'Buses and roads move people.','original'),
('113.14.c.3.A',3,'Which is a natural hazard?','["library", "school bell", "hurricane", "bridge"]'::jsonb,2,'Hurricanes are dangerous natural events.','original'),
('113.14.c.3.B',3,'How might people in a desert adapt to the heat?','["build igloos", "wear heavy coats", "plant rice in snow", "wear light clothing and build thick-walled homes"]'::jsonb,3,'Adapting helps people survive.','original'),
('113.14.c.3.B',4,'People may modify the land by...','["building dams to hold water", "stopping the wind", "erasing mountains by wishing", "rearranging the stars"]'::jsonb,0,'Dams change the land.','original'),
('113.14.c.3.C',3,'What is one effect of pollution?','["it makes the air cleaner", "it can harm water and animals", "it grows more forests", "it brightens the sky"]'::jsonb,1,'Pollution damages the environment.','original'),
('113.14.c.3.C',3,'Which action is conservation?','["dumping trash in a river", "leaving lights on", "recycling paper", "wasting water"]'::jsonb,2,'Recycling protects resources.','original'),
('113.14.c.4.A',3,'Which direction is between north and east?','["northwest", "southwest", "southeast", "northeast"]'::jsonb,3,'Northeast is between north and east.','original'),
('113.14.c.4.A',3,'Which direction is halfway between south and west?','["southwest", "southeast", "northwest", "northeast"]'::jsonb,0,'Southwest is halfway.','original'),
('113.14.c.4.B',3,'A map scale says 1 inch = 10 miles. Two towns are 3 inches apart. About how many miles apart are they?','["13 miles", "30 miles", "300 miles", "3 miles"]'::jsonb,1,'3 times 10 equals 30.','original'),
('113.14.c.4.B',3,'Why is a map scale useful?','["it shows jokes", "it names birds", "it shows real distances", "it tells the weather"]'::jsonb,2,'A scale converts map to real distance.','original'),
('113.14.c.4.C',3,'Which map element helps find places using letters and numbers?','["title", "compass rose", "scale", "grid system"]'::jsonb,3,'A grid helps locate positions.','original'),
('113.14.c.4.C',3,'The legend of a map shows...','["what symbols stand for", "a recipe", "the mapmaker''s lunch", "today''s date"]'::jsonb,0,'A legend explains symbols.','original'),
('113.14.c.5.A',3,'Which is a way to earn money?','["wishing for it", "doing a job", "watching TV", "finding a rainbow"]'::jsonb,1,'Work earns income.','original'),
('113.14.c.5.A',3,'Which is a way to donate money?','["bury it forever", "burn it", "give it to a charity", "trade it for air"]'::jsonb,2,'Donating helps others.','original'),
('113.14.c.5.B',3,'A student earns $10 and decides to spend $6 and save the rest. How much is saved?','["$6", "$10", "$16", "$4"]'::jsonb,3,'10 minus 6 is 4.','original'),
('113.14.c.5.B',3,'Why make a budget?','["to plan spending and saving", "to buy everything", "to lose money", "to hide coins"]'::jsonb,0,'A budget organizes money.','original'),
('113.14.c.6.A',3,'If many people want a toy but few are made, the price will likely...','["disappear", "go up", "stay at zero", "go down"]'::jsonb,1,'High demand and low supply raise price.','original'),
('113.14.c.6.A',3,'If a store has too many apples and few buyers, the price will likely...','["go up", "stay the same", "go down", "double"]'::jsonb,2,'Low demand lowers price.','original'),
('113.14.c.6.B',3,'Scarcity means...','["there is too much of everything", "everything is free", "nothing is wanted", "there is not enough of something for everyone''s wants"]'::jsonb,3,'Scarcity is limited resources.','original'),
('113.14.c.6.C',3,'A bakery spends $2 to make a cupcake and sells it for $5. What is the profit?','["$3", "$5", "$7", "$2"]'::jsonb,0,'5 minus 2 is 3.','original'),
('113.14.c.6.D',3,'Which person started the Ford Motor Company?','["Sam Walton", "Henry Ford", "Ruby Bridges", "Clara Barton"]'::jsonb,1,'Henry Ford founded Ford.','original'),
('113.14.c.6.D',3,'Sam Walton started the store chain called...','["Macy''s", "Sears", "Walmart", "Target"]'::jsonb,2,'Walton founded Walmart.','original'),
('113.14.c.7.A',3,'Which level of government makes laws for a whole state?','["a school club", "a family", "local government", "state government"]'::jsonb,3,'States have their own governments.','original'),
('113.14.c.7.A',3,'Which is the national government?','["the federal government", "a neighborhood club", "a city council", "a school board"]'::jsonb,0,'Federal means national.','original'),
('113.14.c.7.B',3,'How is a mayor usually chosen?','["chosen by a raffle", "elected by voters", "picked by a coin toss", "inherited from a relative"]'::jsonb,1,'Mayors are elected in most cities.','original'),
('113.14.c.7.B',3,'Who leads the United States?','["the governor", "the principal", "the President", "the mayor"]'::jsonb,2,'The President is head of the executive branch.','original'),
('113.14.c.7.C',2,'Which is a service provided by local government?','["movie making", "toy making", "private jets", "trash pickup"]'::jsonb,3,'Cities collect trash.','original'),
('113.14.c.7.C',3,'Which service is provided by the national government?','["national defense", "a bakery", "your lunch", "your neighbor''s lawn"]'::jsonb,0,'The military protects the country.','original'),
('113.14.c.8.A',3,'What did the Declaration of Independence say?','["there would be no laws", "the colonies were free from British rule", "the colonies would stay under Britain", "schools should close"]'::jsonb,1,'It declared independence.','original'),
('113.14.c.8.A',3,'The first ten amendments to the Constitution are called...','["the Declaration", "the Pledge", "the Bill of Rights", "the Anthem"]'::jsonb,2,'They protect individual rights.','original'),
('113.14.c.8.B',4,'The idea that government gets its power from the people is called...','["trade by barter", "rule by one", "power of a king", "consent of the governed"]'::jsonb,3,'The people give their consent.','original'),
('113.14.c.9.A',2,'Which shows good citizenship?','["obeying laws", "cheating", "being unkind", "breaking rules"]'::jsonb,0,'Citizens follow laws.','original'),
('113.14.c.9.B',3,'Helen Keller is remembered for...','["inventing the radio", "working to help people with disabilities", "piloting jets", "painting the Mona Lisa"]'::jsonb,1,'Keller was an author and advocate.','original'),
('113.14.c.9.B',3,'Clara Barton is remembered for starting the...','["National Zoo", "Boy Scouts", "American Red Cross", "U.S. Mint"]'::jsonb,2,'Barton founded the Red Cross.','original'),
('113.14.c.9.B',3,'Ruby Bridges is remembered for being...','["an inventor of the telephone", "a basketball star", "a famous pilot", "the first Black child to attend an all-white school in her city"]'::jsonb,3,'She helped integrate schools.','original'),
('113.14.c.9.C',3,'Serving on a jury is an example of...','["civic responsibility", "a hobby", "a holiday", "a sport"]'::jsonb,0,'Jury duty is a civic duty.','original'),
('113.14.c.9.D',3,'The Red Cross is a(n)...','["bank", "nonprofit organization that helps people in need", "private candy company", "sports team"]'::jsonb,1,'Nonprofits serve the common good.','original'),
('113.14.c.9.E',2,'A class votes on a field trip. What does a majority mean?','["exactly zero", "less than half", "more than half of the votes", "no one decides"]'::jsonb,2,'A majority is more than half.','original'),
('113.14.c.10.A',3,'Why are cultural celebrations important to communities?','["they stop people from meeting", "they end laws", "they remove history", "they honor shared traditions"]'::jsonb,3,'Celebrations preserve heritage.','original'),
('113.14.c.10.B',3,'Both Cinco de Mayo and Juneteenth celebrate parts of history. What can you compare?','["their meanings and customs", "their spelling", "their prices", "their weather only"]'::jsonb,0,'You compare significance and customs.','original'),
('113.14.c.11.A',3,'Hector P. Garcia is remembered for...','["flying around the world", "founding a group that fought for Mexican American civil rights", "painting the Alamo", "inventing a robot"]'::jsonb,1,'He founded the American G.I. Forum.','original'),
('113.14.c.11.A',4,'James A. Lovell is remembered as...','["a Civil War general", "a pop singer", "an astronaut of Apollo 13", "an early mayor"]'::jsonb,2,'Lovell commanded Apollo 13.','original'),
('113.14.c.11.B',3,'Harriet Tubman is remembered for...','["writing the Constitution", "building skyscrapers", "inventing the telephone", "guiding people to freedom on the Underground Railroad"]'::jsonb,3,'She helped many escape slavery.','original'),
('113.14.c.12',3,'How do writers and artists help preserve a community''s culture?','["they tell its stories and show its traditions", "they hide traditions", "they remove history", "they stop celebrations"]'::jsonb,0,'Their works record culture.','original'),
('113.14.c.13.A',3,'Who developed a polio vaccine?','["Bill Gates", "Jonas Salk", "Henry Ford", "Cyrus McCormick"]'::jsonb,1,'Salk developed the vaccine.','original'),
('113.14.c.13.A',3,'Cyrus McCormick invented a machine called the...','["radio", "steam train", "mechanical reaper", "telephone"]'::jsonb,2,'The reaper helped farmers harvest.','original'),
('113.14.c.13.A',3,'Louis Pasteur is known for discovering...','["electric lights", "the telephone", "airplanes", "pasteurization"]'::jsonb,3,'Pasteur''s method kills germs in milk.','original'),
('113.14.c.13.B',3,'How did pasteurization help communities?','["made milk and food safer", "made roads longer", "made houses taller", "made lakes bigger"]'::jsonb,0,'It reduced illness.','original'),
('113.14.c.13.B',3,'How have computers affected communities?','["they ended schools", "they speed up work and sharing information", "they removed all jobs", "they stopped communication"]'::jsonb,1,'Computers help share data quickly.','original'),
('113.14.c.14.A',3,'Which is a good resource for learning about your community''s past?','["a cartoon", "a random guess", "a local museum", "a rumor"]'::jsonb,2,'Museums keep records.','original'),
('113.14.c.14.B',3,'What is a secondary source?','["a diary from the time", "a photo from the event", "a letter from a soldier", "a book written later about an event"]'::jsonb,3,'A secondary source is created after the event.','original'),
('113.14.c.14.B',3,'What is a primary source?','["a firsthand account from someone who was there", "a textbook summary", "an opinion column", "a rumor"]'::jsonb,0,'Primary sources are firsthand.','original'),
('113.14.c.14.C',3,'What is a cause of a flood after heavy rain?','["the sun rises", "rivers overflow", "trees grow taller", "clouds appear"]'::jsonb,1,'Too much water overflows.','original'),
('113.14.c.14.D',3,'A bar graph shows how many books each grade read. What can you tell from it?','["who the principal is", "what the weather is", "which grade read the most", "the lunch menu"]'::jsonb,2,'Bar graphs compare amounts.','original'),
('113.14.c.14.D',3,'A timeline helps you see...','["what to eat", "which team won", "only the weather", "events in order"]'::jsonb,3,'Timelines show sequence.','original'),
('113.14.c.14.E',3,'A pamphlet says, "Our town needs more bike lanes to keep riders safe." What is the central claim?','["more bike lanes are needed", "riders eat lunch", "the town is old", "bike lanes are red"]'::jsonb,0,'The claim is the main point.','original'),
('113.14.c.14.F',3,'What should you include when you share a claim?','["a joke", "supporting evidence", "a rumor", "a random picture"]'::jsonb,1,'Claims need evidence.','original'),
('113.14.c.15',2,'What does the term "community" mean?','["a kind of weather", "a mountain", "a group of people who live or work together", "a type of food"]'::jsonb,2,'Communities share places and goals.','original'),
('113.14.c.15.B',3,'Which timeline label would come first?','["1850", "1950", "2000", "1776"]'::jsonb,3,'The earliest year comes first.','original'),
('113.14.c.15.C',3,'How many years are in a decade?','["10", "100", "1,000", "5"]'::jsonb,0,'A decade is ten years.','original'),
('113.14.c.15.C',3,'How many years are in a century?','["10", "100", "50", "1,000"]'::jsonb,1,'A century is 100 years.','original'),
('113.14.c.15.F',3,'Which is a respectful way to disagree in class?','["interrupt", "shout", "explain your view politely", "insult others"]'::jsonb,2,'Civil discourse is respectful.','original'),
('113.14.c.16.A',3,'A class votes for a new school mascot. This simulates...','["a monarchy", "a mystery", "choosing by coin toss", "democratic decision making"]'::jsonb,3,'Voting is democratic.','original'),
('113.14.c.16.B',3,'What is the first step in solving a community problem?','["identify the problem", "hide it", "blame others", "ignore it"]'::jsonb,0,'You must define the problem first.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
